  1077→                            });
  1078→                        }
  1079→                    }
  1080→                }
  1081→                Err(e) => {
  1082→                    error!(
  1083→                        request = ?req,
  1084→                        %peer_id,
  1085→                        block_root = ?root,
  1086→                        error = ?e,
  1087→                        "Error fetching blobs block root"
  1088→                    );
